import System.Environment; import qualified Data.Text.IO as Text; import Language.JavaScript.Parser; import Language.JavaScript.Process.TreeShake; main = do { [file] <- getArgs; source <- Text.readFile file; case parseProgram source of { Left err -> putStrLn $ "Error: " ++ err; Right ast -> do { putStrLn "Original AST:"; print ast; putStrLn "\nOptimized AST:"; print (treeShake defaultOptions ast) } } }
